'use client';

import { addDays, nextMonday } from 'date-fns';
import { useId, useState } from 'react';
import type { Matcher } from 'react-day-picker';

import { WordRoll } from '@/components/core/word-roll';
import {
  typingSteps,
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import {
  PRESS_LEAD_MS,
  pressedQuietOf,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import { CalendarIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';
import { Label } from '@/registry/ndeko/ui/label';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/registry/ndeko/ui/popover';

import { AnimatedCalendar } from './_parts/animated-calendar';
import { useToday } from './_parts/today';
import { describeTypedDate } from './_parts/typed-date';
import {
  blockedReasonOf,
  UNREADABLE_MESSAGE,
  useTypedDate,
  type DayLimits,
  type TypedDatePicker,
  type TypedDatePreview,
} from './_parts/use-typed-date';

type QuickPickId = 'today' | 'tomorrow' | 'monday';

type QuickPick = {
  id: QuickPickId;
  label: string;
  date: Date | null;
  isBlocked: boolean;
};

type LineKind = 'error' | 'preview' | 'stale' | 'hint';

type Line = {
  kind: LineKind;
  text: string;
};

const LINE_TONE: Record<LineKind, string> = {
  error: 'text-destructive-ink',
  preview: 'text-foreground',
  stale: 'text-muted-foreground',
  hint: 'text-muted-foreground',
};

const REST_TEXT = 'next fri 3pm';

const LATEST_DAYS_AHEAD = 90;

const SUNDAY = 0;

const QUICK_PICK_LABELS: { id: QuickPickId; label: string }[] = [
  { id: 'today', label: 'Today' },
  { id: 'tomorrow', label: 'Tomorrow' },
  { id: 'monday', label: 'Next Monday' },
];

function quickDateOf(id: QuickPickId, today: Date | null) {
  if (today === null) {
    return null;
  }
  if (id === 'tomorrow') {
    return addDays(today, 1);
  }
  if (id === 'monday') {
    return nextMonday(today);
  }
  return today;
}

function isDateBlocked(date: Date | null, limits: DayLimits) {
  if (date === null) {
    return true;
  }
  return blockedReasonOf(date, limits) !== null;
}

function quickPicksOf(today: Date | null, limits: DayLimits): QuickPick[] {
  return QUICK_PICK_LABELS.map(({ id, label }) => {
    const date = quickDateOf(id, today);
    return { id, label, date, isBlocked: isDateBlocked(date, limits) };
  });
}

function disabledMatchersOf(limits: DayLimits) {
  const matchers: Matcher[] = [];
  if (limits.min) {
    matchers.push({ before: limits.min });
  }
  if (limits.max) {
    matchers.push({ after: limits.max });
  }
  if (limits.disabledWeekdays) {
    matchers.push({ dayOfWeek: [...limits.disabledWeekdays] });
  }
  return matchers;
}

function lineOf(
  error: string | null,
  preview: TypedDatePreview | null,
  hint: string
): Line {
  if (error !== null) {
    return { kind: 'error', text: error };
  }
  if (preview === null) {
    return { kind: 'hint', text: hint };
  }
  if (preview.isStale) {
    return { kind: 'stale', text: preview.text };
  }
  return { kind: 'preview', text: preview.text };
}

function hintOf(withTime: boolean) {
  if (withTime) {
    return 'Try “next fri 3pm” or “in 3 days”';
  }
  return 'Try “next fri”, “in 3 days” or “14 nov”';
}

export type TypedDateFieldProps = {
  label: string;
  picker: TypedDatePicker;
  today: Date | null;
  limits: DayLimits;
  withTime: boolean;
  pressedPick?: QuickPickId | null;
};

export function TypedDateField({
  label,
  picker,
  today,
  limits,
  withTime,
  pressedPick = null,
}: TypedDateFieldProps) {
  const id = useId();
  const lineId = `${id}-line`;
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);
  const [announcement, setAnnouncement] = useState('');
  const { text, changeText, value, preview, error, commit, pickDay } = picker;
  const line = lineOf(error, preview, hintOf(withTime));
  const picks = quickPicksOf(today, limits);
  const matchers = disabledMatchersOf(limits);
  const calendarMonth = value?.date ?? today ?? undefined;

  function announceSet(date: Date, hasTime: boolean) {
    if (today === null) {
      return;
    }
    const spoken = describeTypedDate({ date, hasTime }, today);
    setAnnouncement(`${label} set to ${spoken}`);
  }

  function commitFromPerson() {
    const committed = commit();
    if (committed) {
      announceSet(committed.date, committed.hasTime);
      return;
    }
    const hasText = text.trim() !== '';
    if (hasText) {
      setAnnouncement(error ?? UNREADABLE_MESSAGE);
    }
  }

  function pickFromPerson(date: Date) {
    const picked = pickDay(date);
    if (picked) {
      announceSet(picked.date, picked.hasTime);
    }
  }

  function pickQuick(pick: QuickPick) {
    if (pick.date === null) {
      return;
    }
    pickFromPerson(pick.date);
  }

  function selectInCalendar(date: Date | undefined) {
    if (!date) {
      return;
    }
    pickFromPerson(date);
    setIsCalendarOpen(false);
  }

  function commitOnEnter(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key !== 'Enter') {
      return;
    }
    event.preventDefault();
    commitFromPerson();
  }

  return (
    <div className='flex w-full flex-col gap-2'>
      <Label htmlFor={id}>{label}</Label>
      <div className='relative'>
        <Input
          id={id}
          value={text}
          onChange={(event) => changeText(event.currentTarget.value)}
          onKeyDown={commitOnEnter}
          onBlur={commitFromPerson}
          placeholder='Type a date'
          autoComplete='off'
          spellCheck={false}
          aria-invalid={error !== null}
          aria-describedby={lineId}
          className='pe-10'
        />
        <Popover open={isCalendarOpen} onOpenChange={setIsCalendarOpen}>
          <PopoverTrigger
            render={
              <Button
                variant='ghost'
                size='icon-sm'
                aria-label='Open the calendar'
                className='text-muted-foreground hover:text-foreground absolute end-0.5 top-0.5 size-7'
              />
            }
          >
            <CalendarIcon className='size-4' />
          </PopoverTrigger>
          <PopoverContent className='w-auto p-2' align='end'>
            <AnimatedCalendar
              mode='single'
              selected={value?.date}
              onSelect={selectInCalendar}
              defaultMonth={calendarMonth}
              disabled={matchers}
            />
          </PopoverContent>
        </Popover>
      </div>
      <div id={lineId} className='flex min-h-5 items-center text-xs'>
        <WordRoll text={line.text} className={LINE_TONE[line.kind]} />
      </div>
      <div className='flex flex-wrap gap-1.5'>
        {picks.map((pick) => (
          <Button
            key={pick.id}
            variant='outline'
            size='sm'
            disabled={pick.isBlocked}
            onClick={() => pickQuick(pick)}
            className={pressedQuietOf(pressedPick === pick.id)}
          >
            {pick.label}
          </Button>
        ))}
      </div>
      <LiveRegion message={announcement} />
    </div>
  );
}

export default function CalendarDatePicker29() {
  const today = useToday();
  const { pressed, press } = usePress<QuickPickId>();
  const limits: DayLimits = {};
  if (today !== null) {
    limits.min = today;
    limits.max = addDays(today, LATEST_DAYS_AHEAD);
    limits.disabledWeekdays = [SUNDAY];
  }
  const picker = useTypedDate({
    today,
    withTime: true,
    initialText: REST_TEXT,
    ...limits,
  });

  function pickNextMonday() {
    if (today === null) {
      return;
    }
    picker.pickDay(nextMonday(today));
  }

  const steps: AutoplayStep[] = [
    { after: 2400, run: () => picker.changeText('') },
    ...typingSteps('in 3 days', picker.changeText, {
      startAfter: 500,
      characterMs: 70,
    }),
    { after: 1000, run: () => picker.commit() },
    { after: 1800, run: () => press('monday') },
    { after: PRESS_LEAD_MS, run: pickNextMonday },
    { after: 1800, run: () => picker.changeText('') },
    ...typingSteps('someday', picker.changeText, {
      startAfter: 500,
      characterMs: 70,
    }),
    { after: 1000, run: () => picker.commit() },
    { after: 1800, run: () => picker.changeText('') },
    ...typingSteps(REST_TEXT, picker.changeText, {
      startAfter: 500,
      characterMs: 70,
    }),
  ];
  const { ref } = useAutoplay(steps, {
    loopAfter: 3200,
    onReset: () => picker.reset(REST_TEXT),
  });

  useKeptHeight(ref);

  return (
    <div ref={ref} className='min-h-[10rem] w-full max-w-xs'>
      <TypedDateField
        label='Due date'
        picker={picker}
        today={today}
        limits={limits}
        withTime
        pressedPick={pressed}
      />
    </div>
  );
}

'use client';

import { differenceInCalendarDays } from 'date-fns';
import {
  motion,
  type TargetAndTransition,
  type Transition,
} from 'motion/react';
import { useState } from 'react';
import {
  Day,
  useDayPicker,
  type DayProps,
  type MonthProps,
} from 'react-day-picker';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Calendar } from '@/registry/ndeko/ui/calendar';

type CalendarProps = React.ComponentProps<typeof Calendar>;

type ShownMonth = { time: number; direction: number };

const MONTH_SHIFT_PX = 12;
const RANGE_STEP_MS = 12;
const RANGE_GROWTH_MAX_MS = 240;

const MONTH_TRANSITION: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};

const MONTH_AT_REST: TargetAndTransition = { opacity: 1, x: 0 };

const SETTLING_DAY_BUTTON = [
  'transition-[color,background-color,border-radius,box-shadow,scale] ease-(--ease-out-strong) active:scale-90',
  'group-[.range-middle]:[transition-delay:var(--range-delay),var(--range-delay),0ms,0ms,0ms]',
].join(' ');

function rangeStartOf(selected: unknown) {
  if (!selected) {
    return undefined;
  }
  if (typeof selected !== 'object') {
    return undefined;
  }
  if (!('from' in selected)) {
    return undefined;
  }
  return selected.from as Date | undefined;
}

function rangeDelayOf(day: Date, rangeStart: Date | undefined) {
  if (!rangeStart) {
    return '0ms';
  }
  const step = differenceInCalendarDays(day, rangeStart);
  const delay = Math.min(step * RANGE_STEP_MS, RANGE_GROWTH_MAX_MS);
  const positiveDelay = Math.max(0, delay);
  return `${positiveDelay}ms`;
}

function monthEnterOf(direction: number, shouldReduceMotion: boolean | null) {
  if (direction === 0) {
    return false;
  }
  if (shouldReduceMotion) {
    return { opacity: 0 };
  }
  const offset = direction * MONTH_SHIFT_PX;
  return { opacity: 0, x: offset };
}

function GrowingRangeDay({ style, ...props }: DayProps) {
  const { selected } = useDayPicker();
  const rangeStart = rangeStartOf(selected);
  const delay = rangeDelayOf(props.day.date, rangeStart);
  const dayStyle = { ...style, '--range-delay': delay } as React.CSSProperties;

  return <Day {...props} style={dayStyle} />;
}

function SlidingMonth({
  calendarMonth,
  displayIndex,
  children,
  ...props
}: MonthProps) {
  const time = calendarMonth.date.getTime();
  const [shown, setShown] = useState<ShownMonth>({ time, direction: 0 });
  const shouldReduceMotion = usePrefersReducedMotion();

  if (shown.time !== time) {
    const direction = Math.sign(time - shown.time);
    setShown({ time, direction });
  }

  return (
    <div data-display-index={displayIndex} {...props}>
      <AnimatedSize>
        <motion.div
          key={time}
          initial={monthEnterOf(shown.direction, shouldReduceMotion)}
          animate={MONTH_AT_REST}
          transition={MONTH_TRANSITION}
        >
          {children}
        </motion.div>
      </AnimatedSize>
    </div>
  );
}

function withSettlingDays(classNames: CalendarProps['classNames']) {
  const dayButton = cn(SETTLING_DAY_BUTTON, classNames?.day_button);
  return { ...classNames, day_button: dayButton };
}

/**
 * The calendar primitive with the date picker micro-interactions: a picked day settles in,
 * a range grows from its start to its end, a new month slides in from the side it comes from
 * and the card resizes to the number of weeks.
 */
function AnimatedCalendar({ classNames, components, ...props }: CalendarProps) {
  return (
    <Calendar
      classNames={withSettlingDays(classNames)}
      components={{ Day: GrowingRangeDay, Month: SlidingMonth, ...components }}
      {...props}
    />
  );
}

export { AnimatedCalendar };

'use client';

import { startOfDay } from 'date-fns';
import { useSyncExternalStore } from 'react';

let cachedToday: Date | null = null;

function subscribeNever() {
  return () => {};
}

function readToday() {
  if (cachedToday === null) {
    cachedToday = startOfDay(new Date());
  }
  return cachedToday;
}

function readNothing() {
  return null;
}

/** The server and the first client render know no day, so what depends on it appears once the page is live. */
export function useToday() {
  return useSyncExternalStore(subscribeNever, readToday, readNothing);
}

import {
  addDays,
  addMonths,
  addWeeks,
  addYears,
  format,
  isAfter,
  isBefore,
  isSameYear,
  startOfDay,
} from 'date-fns';

export type TypedDate = {
  date: Date;
  hasTime: boolean;
};

export type TypedDateOptions = {
  today: Date;
  withTime: boolean;
  /** Which of day and month comes first in numbers such as 14/11. */
  isDayFirst?: boolean;
  /** Where a date with no year lands: the next time it comes round, or the last time it did. */
  direction?: 'future' | 'past';
};

export type TypedDateReading =
  | { status: 'empty' }
  | { status: 'unreadable' }
  | { status: 'ready'; value: TypedDate };

type Clock = {
  hours: number;
  minutes: number;
};

type Parts = {
  year: number;
  month: number;
  day: number;
};

const MONTHS = [
  'january',
  'february',
  'march',
  'april',
  'may',
  'june',
  'july',
  'august',
  'september',
  'october',
  'november',
  'december',
];

const WEEKDAYS = [
  'sunday',
  'monday',
  'tuesday',
  'wednesday',
  'thursday',
  'friday',
  'saturday',
];

const WEEKDAY_LEADS = ['', 'this', 'next', 'on'];

const MERIDIEM_TIME = /\b(?:at\s+)?(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/;
const CLOCK_TIME = /\b(?:at\s+)?(\d{1,2}):(\d{2})\b/;
const NOON = /\b(?:at\s+)?noon\b/;
const ISO_DATE = /^(\d{4})-(\d{1,2})-(\d{1,2})$/;
const NUMERIC_DATE = /^(\d{1,2})[./-](\d{1,2})(?:[./-](\d{4}|\d{2}))?$/;
const RELATIVE_DATE = /^in (\d+) (days?|d|weeks?|w|months?|years?|y)$/;
const ORDINAL_SUFFIX = /^(\d{1,2})(?:st|nd|rd|th)$/;

function normalized(text: string) {
  const lower = text.toLowerCase().replace(/,/g, ' ');
  const spaced = lower.replace(/(\d)t(\d)/g, '$1 $2');
  return spaced.replace(/\s+/g, ' ').trim();
}

function withoutMatch(text: string, match: RegExpMatchArray) {
  const before = text.slice(0, match.index);
  const after = text.slice((match.index ?? 0) + match[0].length);
  return `${before} ${after}`.replace(/\s+/g, ' ').trim();
}

function meridiemClockOf(match: RegExpMatchArray): Clock | null {
  const hour = Number(match[1]);
  const minutes = Number(match[2] ?? '0');
  const isHourValid = hour >= 1 && hour <= 12;
  const isMinuteValid = minutes <= 59;
  if (!isHourValid || !isMinuteValid) {
    return null;
  }
  const isPm = match[3] === 'pm';
  const hoursOfDay = hour % 12;
  if (isPm) {
    return { hours: hoursOfDay + 12, minutes };
  }
  return { hours: hoursOfDay, minutes };
}

function clockOf(match: RegExpMatchArray): Clock | null {
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  const isValid = hours <= 23 && minutes <= 59;
  if (!isValid) {
    return null;
  }
  return { hours, minutes };
}

type TimeSplit = {
  rest: string;
  clock: Clock | null;
  isBroken: boolean;
};

function splitTime(text: string): TimeSplit {
  const meridiem = text.match(MERIDIEM_TIME);
  if (meridiem) {
    const clock = meridiemClockOf(meridiem);
    return {
      rest: withoutMatch(text, meridiem),
      clock,
      isBroken: clock === null,
    };
  }
  const clockMatch = text.match(CLOCK_TIME);
  if (clockMatch) {
    const clock = clockOf(clockMatch);
    return {
      rest: withoutMatch(text, clockMatch),
      clock,
      isBroken: clock === null,
    };
  }
  const noon = text.match(NOON);
  if (noon) {
    return {
      rest: withoutMatch(text, noon),
      clock: { hours: 12, minutes: 0 },
      isBroken: false,
    };
  }
  return { rest: text, clock: null, isBroken: false };
}

function isRealDate({ year, month, day }: Parts) {
  const date = new Date(year, month, day);
  const isSameYearNumber = date.getFullYear() === year;
  const isSameMonth = date.getMonth() === month;
  const isSameDay = date.getDate() === day;
  return isSameYearNumber && isSameMonth && isSameDay;
}

function dateOfParts(parts: Parts) {
  if (!isRealDate(parts)) {
    return null;
  }
  return new Date(parts.year, parts.month, parts.day);
}

/** With no year, "14 nov" typed in December means next year, unless the field looks back in time. */
function withNearestYear(
  parts: Parts,
  today: Date,
  direction: 'future' | 'past'
) {
  const thisYear = dateOfParts(parts);
  if (thisYear === null) {
    return null;
  }
  if (direction === 'past') {
    if (!isAfter(thisYear, today)) {
      return thisYear;
    }
    return dateOfParts({ ...parts, year: parts.year - 1 });
  }
  if (!isBefore(thisYear, today)) {
    return thisYear;
  }
  return dateOfParts({ ...parts, year: parts.year + 1 });
}

export function monthIndexOf(word: string) {
  if (word.length < 3) {
    return -1;
  }
  return MONTHS.findIndex((name) => name.startsWith(word));
}

function weekdayIndexOf(word: string) {
  if (word.length < 3) {
    return -1;
  }
  return WEEKDAYS.findIndex((name) => name.startsWith(word));
}

function dayNumberOf(word: string) {
  const ordinal = word.match(ORDINAL_SUFFIX);
  if (ordinal) {
    return Number(ordinal[1]);
  }
  if (/^\d{1,2}$/.test(word)) {
    return Number(word);
  }
  return null;
}

function weekdayDateOf(today: Date, weekday: number, isNext: boolean) {
  const gap = (weekday - today.getDay() + 7) % 7;
  const mustBeLater = isNext && gap === 0;
  if (mustBeLater) {
    return addDays(today, 7);
  }
  return addDays(today, gap);
}

function relativeDateOf(match: RegExpMatchArray, today: Date) {
  const amount = Number(match[1]);
  const unit = match[2][0];
  if (unit === 'w') {
    return addWeeks(today, amount);
  }
  if (unit === 'm') {
    return addMonths(today, amount);
  }
  if (unit === 'y') {
    return addYears(today, amount);
  }
  return addDays(today, amount);
}

function keywordDateOf(text: string, today: Date) {
  if (text === '' || text === 'today') {
    return today;
  }
  if (text === 'tomorrow' || text === 'tmrw') {
    return addDays(today, 1);
  }
  if (text === 'yesterday') {
    return addDays(today, -1);
  }
  if (text === 'next week') {
    return addWeeks(today, 1);
  }
  if (text === 'next month') {
    return addMonths(today, 1);
  }
  return null;
}

function weekdayPhraseDateOf(text: string, today: Date) {
  const words = text.split(' ');
  const word = words[words.length - 1];
  const lead = words.slice(0, -1).join(' ');
  const hasKnownLead = WEEKDAY_LEADS.includes(lead);
  const weekday = weekdayIndexOf(word);
  if (!hasKnownLead || weekday === -1) {
    return null;
  }
  return weekdayDateOf(today, weekday, lead === 'next');
}

type DayAndMonth = {
  day: number;
  month: number;
};

/** A month that cannot be one (14/11 read month first) is taken the other way round. */
function dayAndMonthOf(
  first: number,
  second: number,
  isDayFirst: boolean
): DayAndMonth {
  const ordered = { day: second, month: first };
  if (isDayFirst) {
    ordered.day = first;
    ordered.month = second;
  }
  const needsSwap = ordered.month > 12 && ordered.day <= 12;
  if (needsSwap) {
    return { day: ordered.month, month: ordered.day };
  }
  return ordered;
}

function numericDateOf(match: RegExpMatchArray, options: TypedDateOptions) {
  const first = Number(match[1]);
  const second = Number(match[2]);
  const rawYear = match[3];
  const isDayFirst = options.isDayFirst ?? false;
  const { day, month } = dayAndMonthOf(first, second, isDayFirst);
  return datePartsDateOf(day, month - 1, rawYear, options);
}

function datePartsDateOf(
  day: number,
  month: number,
  rawYear: string | undefined,
  options: TypedDateOptions
) {
  const { today, direction = 'future' } = options;
  if (rawYear === undefined) {
    const parts = { year: today.getFullYear(), month, day };
    return withNearestYear(parts, today, direction);
  }
  const year = fullYearOf(rawYear);
  return dateOfParts({ year, month, day });
}

function fullYearOf(rawYear: string) {
  const year = Number(rawYear);
  if (rawYear.length === 2) {
    return 2000 + year;
  }
  return year;
}

function monthNameDateOf(text: string, options: TypedDateOptions) {
  const words = text.split(' ').filter((word) => word !== 'of');
  const isShort = words.length === 2 || words.length === 3;
  if (!isShort) {
    return null;
  }
  const [first, second, third] = words;
  const dayFirst = dayNumberOf(first);
  const monthSecond = monthIndexOf(second);
  if (dayFirst !== null && monthSecond !== -1) {
    return datePartsDateOf(dayFirst, monthSecond, third, options);
  }
  const monthFirst = monthIndexOf(first);
  const daySecond = dayNumberOf(second);
  if (monthFirst !== -1 && daySecond !== null) {
    return datePartsDateOf(daySecond, monthFirst, third, options);
  }
  return null;
}

function dateOfText(text: string, options: TypedDateOptions) {
  const { today } = options;
  const keyword = keywordDateOf(text, today);
  if (keyword) {
    return keyword;
  }
  const weekday = weekdayPhraseDateOf(text, today);
  if (weekday) {
    return weekday;
  }
  const relative = text.match(RELATIVE_DATE);
  if (relative) {
    return relativeDateOf(relative, today);
  }
  const iso = text.match(ISO_DATE);
  if (iso) {
    return dateOfParts({
      year: Number(iso[1]),
      month: Number(iso[2]) - 1,
      day: Number(iso[3]),
    });
  }
  const numeric = text.match(NUMERIC_DATE);
  if (numeric) {
    return numericDateOf(numeric, options);
  }
  return monthNameDateOf(text, options);
}

export function readTypedDate(
  text: string,
  options: TypedDateOptions
): TypedDateReading {
  const clean = normalized(text);
  if (clean === '') {
    return { status: 'empty' };
  }
  const { rest, clock, isBroken } = splitTime(clean);
  if (isBroken) {
    return { status: 'unreadable' };
  }
  const isTimeAllowed = options.withTime || clock === null;
  if (!isTimeAllowed) {
    return { status: 'unreadable' };
  }
  const day = dateOfText(rest, options);
  if (day === null) {
    return { status: 'unreadable' };
  }
  const start = startOfDay(day);
  if (clock === null) {
    return { status: 'ready', value: { date: start, hasTime: false } };
  }
  const withClock = new Date(start);
  withClock.setHours(clock.hours, clock.minutes, 0, 0);
  return { status: 'ready', value: { date: withClock, hasTime: true } };
}

function dayPatternOf(hasThisYear: boolean) {
  if (hasThisYear) {
    return 'EEEE d MMMM';
  }
  return 'EEEE d MMMM y';
}

export function describeTypedDate(value: TypedDate, today: Date) {
  const hasThisYear = isSameYear(value.date, today);
  const dayPattern = dayPatternOf(hasThisYear);
  const day = format(value.date, dayPattern);
  if (!value.hasTime) {
    return day;
  }
  const time = format(value.date, 'HH:mm');
  return `${day}, ${time}`;
}

export function formatTypedDate(value: TypedDate) {
  const day = format(value.date, 'd MMM y');
  if (!value.hasTime) {
    return day;
  }
  const time = format(value.date, 'HH:mm');
  return `${day}, ${time}`;
}

export function isDayFirstIn(locale: string) {
  const sample = new Date(2026, 10, 13);
  const parts = new Intl.DateTimeFormat(locale).formatToParts(sample);
  const order = parts.map((part) => part.type);
  return order.indexOf('day') < order.indexOf('month');
}

'use client';

import { format, isAfter, isBefore, startOfDay } from 'date-fns';
import { useState } from 'react';

import {
  describeTypedDate,
  formatTypedDate,
  isDayFirstIn,
  readTypedDate,
  type TypedDate,
  type TypedDateReading,
} from './typed-date';

export type DayLimits = {
  min?: Date;
  max?: Date;
  /** Days of the week that cannot be picked, 0 for Sunday. */
  disabledWeekdays?: readonly number[];
};

export type TypedDatePreview = {
  text: string;
  /** The text typed so far reads as nothing yet, so this is the last date it did read as. */
  isStale: boolean;
};

type UseTypedDateOptions = DayLimits & {
  /** Null until the page is live, since the day is only known in the browser. */
  today: Date | null;
  withTime: boolean;
  initialText?: string;
};

export const UNREADABLE_MESSAGE = 'Can’t read that. Try “next fri” or “14 nov”';

const EMPTY_READING: TypedDateReading = { status: 'empty' };

export function blockedReasonOf(date: Date, limits: DayLimits) {
  const day = startOfDay(date);
  const { min, max, disabledWeekdays } = limits;
  if (min && isBefore(day, startOfDay(min))) {
    return `Pick a day from ${format(min, 'd MMM')}`;
  }
  if (max && isAfter(day, startOfDay(max))) {
    return `Pick a day up to ${format(max, 'd MMM')}`;
  }
  if (disabledWeekdays?.includes(day.getDay())) {
    return `${format(day, 'EEEE')}s are not available`;
  }
  return null;
}

function localeIsDayFirst() {
  if (typeof navigator === 'undefined') {
    return false;
  }
  return isDayFirstIn(navigator.language);
}

function isSameTypedDate(first: TypedDate | null, second: TypedDate) {
  if (first === null) {
    return false;
  }
  const isSameTime = first.date.getTime() === second.date.getTime();
  return isSameTime && first.hasTime === second.hasTime;
}

function withTimeOf(date: Date, source: TypedDate | null): TypedDate {
  if (source?.hasTime) {
    const merged = startOfDay(date);
    merged.setHours(source.date.getHours(), source.date.getMinutes(), 0, 0);
    return { date: merged, hasTime: true };
  }
  return { date: startOfDay(date), hasTime: false };
}

function errorOf(
  blockedReason: string | null,
  isTouched: boolean,
  reading: TypedDateReading
) {
  if (blockedReason !== null) {
    return blockedReason;
  }
  const isUnreadable = reading.status === 'unreadable';
  if (isTouched && isUnreadable) {
    return UNREADABLE_MESSAGE;
  }
  return null;
}

export function useTypedDate({
  today,
  withTime,
  initialText = '',
  min,
  max,
  disabledWeekdays,
}: UseTypedDateOptions) {
  const [text, setText] = useState(initialText);
  const [value, setValue] = useState<TypedDate | null>(null);
  const [lastReady, setLastReady] = useState<TypedDate | null>(null);
  const [touchedText, setTouchedText] = useState<string | null>(null);
  const [isDayFirst] = useState(localeIsDayFirst);
  const limits: DayLimits = { min, max, disabledWeekdays };
  let reading = EMPTY_READING;
  if (today !== null) {
    reading = readTypedDate(text, { today, withTime, isDayFirst });
  }

  if (
    reading.status === 'ready' &&
    !isSameTypedDate(lastReady, reading.value)
  ) {
    setLastReady(reading.value);
  }
  if (reading.status === 'empty' && lastReady !== null) {
    setLastReady(null);
  }

  let blockedReason: string | null = null;
  if (reading.status === 'ready') {
    blockedReason = blockedReasonOf(reading.value.date, limits);
  }
  const isTouched = touchedText === text;
  const error = errorOf(blockedReason, isTouched, reading);

  let preview: TypedDatePreview | null = null;
  if (today !== null && reading.status === 'ready') {
    preview = { text: describeTypedDate(reading.value, today), isStale: false };
  }
  if (today !== null && reading.status === 'unreadable' && lastReady !== null) {
    preview = { text: describeTypedDate(lastReady, today), isStale: true };
  }

  function commit() {
    if (reading.status === 'empty') {
      setValue(null);
      return null;
    }
    if (reading.status === 'unreadable' || blockedReason !== null) {
      setTouchedText(text);
      return null;
    }
    setValue(reading.value);
    setText(formatTypedDate(reading.value));
    return reading.value;
  }

  function pickDay(date: Date) {
    const next = withTimeOf(date, value ?? lastReady);
    const reason = blockedReasonOf(next.date, limits);
    setText(formatTypedDate(next));
    if (reason !== null) {
      return null;
    }
    setValue(next);
    return next;
  }

  function reset(nextText: string) {
    setText(nextText);
    setValue(null);
    setLastReady(null);
    setTouchedText(null);
  }

  return {
    text,
    changeText: setText,
    value,
    preview,
    error,
    commit,
    pickDay,
    reset,
  };
}

export type TypedDatePicker = ReturnType<typeof useTypedDate>;
